    assert_eq!(candidate("qwertyuiopasdfghjklzxcvbnm", "*qwe*cvb*"), Error: too many values to unpack (expected 3));
    assert_eq!(candidate("abcdefghijabcdefghij", "*def*g*h*"), Error: too many values to unpack (expected 3));
    assert_eq!(candidate("abcdeabcdeabcde", "*bcde*bcde"), 9);
    assert_eq!(candidate("thisisaverylongteststring", "*very*test*"), Error: too many values to unpack (expected 3));
    assert_eq!(candidate("mississippi", "*iss*ss*"), Error: too many values to unpack (expected 3));
    assert_eq!(candidate("longstringwithvariouscharacters", "*with*char*"), Error: too many values to unpack (expected 3));
    assert_eq!(candidate("mississippi", "miss*ss*"), 7);
    assert_eq!(candidate("abcdabcdabcd", "*abc*d*d*"), Error: too many values to unpack (expected 3));
    assert_eq!(candidate("banana", "*an*na*"), Error: too many values to unpack (expected 3));
    assert_eq!(candidate("patternmatching", "*tern*atch*"), Error: too many values to unpack (expected 3));
    assert_eq!(candidate("abcdefgabcdefg", "*abc*def*g*"), Error: too many values to unpack (expected 3));
    assert_eq!(candidate("hellohellohello", "*hello*lo"), 10);
}
